def get_contradiction_matrix(improve_param, worsen_param, contradiction_type='hardware'):
    """
    查询矛盾矩阵，获取发明原则编号
    :param improve_param: 改善的参数编号 (硬件1-39，软件1-24)
    :param worsen_param: 恶化的参数编号 (硬件1-39，软件1-24)
    :param contradiction_type: 矛盾类型，'hardware'表示硬件矛盾（使用39矩阵），'software'表示软件矛盾（使用24矩阵）
    :return: 4个发明原则编号的列表，如果为[0,0,0,0]表示没有对应的原则
    """
    if contradiction_type == 'software':
        # 软件矛盾矩阵（24x24）
        if improve_param < 1 or improve_param > 24 or worsen_param < 1 or worsen_param > 24:
            return [0, 0, 0, 0]
        row = improve_param - 1
        col = worsen_param - 1
        return CM24m24[row][col]
    else:
        # 硬件矛盾矩阵（39x39）
        if improve_param < 1 or improve_param > 39 or worsen_param < 1 or worsen_param > 39:
            return [0, 0, 0, 0]
        row = improve_param - 1
        col = worsen_param - 1
        return CM39m39[row][col]

def read_pdf_content(pdf_path):
    """
    读取PDF文件内容
    :param pdf_path: PDF文件路径
    :return: PDF文本内容，如果读取失败返回None
    """
    try:
        import PyPDF2
        with open(pdf_path, 'rb') as file:
            pdf_reader = PyPDF2.PdfReader(file)
            text = ""
            for page in pdf_reader.pages:
                text += page.extract_text() + "\n"
            return text.strip()
    except ImportError:
        # 如果PyPDF2不可用，尝试使用pdfplumber
        try:
            import pdfplumber
            with pdfplumber.open(pdf_path) as pdf:
                text = ""
                for page in pdf.pages:
                    text += page.extract_text() + "\n"
                return text.strip()
        except ImportError:
            return None
    except Exception as e:
        print(f"读取PDF文件失败: {e}")
        return None

def get_principle_pdf_path(principle_num):
    """
    根据发明原则编号获取PDF文件路径（已废弃，保留用于兼容性）
    现在从数据库读取，此函数仅用于向后兼容
    :param principle_num: 发明原则编号 (1-40)
    :return: PDF文件路径，如果文件不存在返回None
    """
    import os
    if principle_num == 0:
        return None
    
    # 根据principle目录下的文件命名规则查找
    principle_dir = "principle"
    if os.path.exists(principle_dir):
        # 文件名格式：编号+名称.pdf，例如：1分割.pdf
        for filename in os.listdir(principle_dir):
            if filename.startswith(str(principle_num)) and filename.endswith('.pdf'):
                return os.path.join(principle_dir, filename)
    
    return None

def get_principle_from_db(principle_num):
    """
    从数据库获取发明原则
    :param principle_num: 发明原则编号 (1-40)
    :return: 原则字典，包含number, name, content，如果不存在返回None
    """
    try:
        from database import get_principle_by_number
        return get_principle_by_number(principle_num)
    except ImportError:
        # 如果数据库模块不可用，回退到文件读取
        pdf_path = get_principle_pdf_path(principle_num)
        if pdf_path and os.path.exists(pdf_path):
            content = read_pdf_content(pdf_path)
            if content:
                return {
                    'number': principle_num,
                    'name': get_principle_name(principle_num),
                    'content': content
                }
        return None

def get_principle_name(principle_num):
    """
    根据发明原则编号获取原则名称
    :param principle_num: 发明原则编号 (1-40)
    :return: 原则名称
    """
    principle_names = {
        1: "分割", 2: "抽取", 3: "局部特性", 4: "非对称", 5: "结合",
        6: "万用性", 7: "套叠", 8: "平衡力", 9: "预先反作用", 10: "预先动作",
        11: "预先缓和", 12: "等位性", 13: "倒转反向", 14: "球面化曲面化", 15: "动态",
        16: "局部或过度的动作", 17: "改变到新的维度", 18: "机械振动", 19: "周期性动作", 20: "有效动作的持续",
        21: "快速通过", 22: "转有害为有益", 23: "回馈", 24: "中介物", 25: "自助",
        26: "复制", 27: "取代以便宜寿命短的对象", 28: "更换机械系统", 29: "气压或液压", 30: "弹性膜或薄膜",
        31: "多孔材料", 32: "改变颜色", 33: "同质性", 34: "抛弃和再生", 35: "变化物理或化学状态",
        36: "相变", 37: "热膨胀", 38: "强氧化剂", 39: "惰性环境", 40: "复合材料"
    }
    return principle_names.get(principle_num, f"原则{principle_num}")
